import { useCallback, useEffect, useState } from 'react';
import { ChevronUp, ConciergeBell } from 'lucide-react';
import './index.css';
import { dishById, type Dish } from './data/menu';
import { eur, plural } from './lib/format';
import {
  DEFAULT_TABLE, cartCount, cartTotal, clearStorage, newKey, seedCart, seedOrders, stageOf, usePersistent,
  type CartLine, type Order, type WaiterCall,
} from './lib/store';
import MenuView from './components/MenuView';
import DishSheet from './components/DishSheet';
import OrderPanel, { type PanelTab } from './components/OrderPanel';
import WaiterSheet from './components/WaiterSheet';
import AmbientAside from './components/AmbientAside';

type Editing = { dish: Dish; line?: CartLine } | null;

export default function App() {
  const [cart, setCart] = usePersistent<CartLine[]>('cart', seedCart);
  const [orders, setOrders] = usePersistent<Order[]>('orders', seedOrders);
  const [table, setTable] = usePersistent<number>('table', DEFAULT_TABLE);
  const [waiterCall, setWaiterCall] = usePersistent<WaiterCall | null>('waiter', null);
  const [tab, setTab] = useState<PanelTab>('pedido');
  const [editing, setEditing] = useState<Editing>(null);
  const [orderOpen, setOrderOpen] = useState(false);
  const [waiterOpen, setWaiterOpen] = useState(false);
  const [toast, setToast] = useState<{ id: number; text: string } | null>(null);
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 2600);
    return () => clearTimeout(t);
  }, [toast]);

  const notify = (text: string) => setToast({ id: Date.now(), text });
  const inCart = (dishId: string) => cart.filter(l => l.dishId === dishId).reduce((s, l) => s + l.qty, 0);

  const saveLine = (line: CartLine) => {
    const name = dishById(line.dishId)?.name ?? 'Plato';
    setCart(c => (c.some(l => l.key === line.key) ? c.map(l => (l.key === line.key ? line : l)) : [...c, line]));
    notify(editing?.line ? 'Cambios guardados' : `${name} añadido al pedido`);
    setEditing(null);
    setTab('pedido');
  };

  const quickAdd = (dish: Dish) => {
    if (dish.doneness) return setEditing({ dish }); // hay que elegir el punto
    setCart(c => {
      const same = c.find(l => l.dishId === dish.id && !l.extras.length && !l.notes);
      if (same) return c.map(l => (l === same ? { ...l, qty: Math.min(20, l.qty + 1) } : l));
      return [...c, { key: newKey(), dishId: dish.id, qty: 1, extras: [], notes: '' }];
    });
    setTab('pedido');
    notify(`${dish.name} añadido al pedido`);
  };

  const sendOrder = () => {
    if (!cart.length) return;
    const number = orders.reduce((m, o) => Math.max(m, o.number), 0) + 1;
    const order: Order = { id: newKey(), number, table, lines: cart, total: cartTotal(cart), sentAt: Date.now() };
    setOrders(os => [...os, order]);
    setCart([]);
    setTab('seguimiento');
    notify(`Pedido ${number} enviado a cocina`);
  };

  const callWaiter = (reason = 'Necesito ayuda') => {
    setWaiterCall({ reason, at: Date.now() });
    setWaiterOpen(false);
    notify(`Avisado. ${reason === 'Pedir la cuenta' ? 'Te traemos la cuenta' : 'Vamos enseguida'}`);
  };

  const reset = () => {
    clearStorage();
    setCart(seedCart());
    setOrders(seedOrders());
    setTable(DEFAULT_TABLE);
    setWaiterCall(null);
    setTab('pedido');
    notify('Datos de ejemplo restablecidos');
  };

  const closeEditing = useCallback(() => setEditing(null), []);
  const closeWaiter = useCallback(() => setWaiterOpen(false), []);

  const count = cartCount(cart);
  const cooking = orders.filter(o => stageOf(o, now) !== 'servido').length;

  const panelProps = {
    tab, onTab: setTab, cart, orders, table, now, waiterCall,
    onTable: setTable,
    onQty: (key: string, qty: number) => setCart(c => c.map(l => (l.key === key ? { ...l, qty } : l))),
    onRemove: (key: string) => setCart(c => c.filter(l => l.key !== key)),
    onEdit: (line: CartLine) => { const dish = dishById(line.dishId); if (dish) setEditing({ dish, line }); },
    onSend: sendOrder,
    onCallWaiter: (reason?: string) => (reason ? callWaiter(reason) : setWaiterOpen(true)),
  };

  return (
    <div className="brasa h-[100dvh] overflow-hidden bg-[#15100D] text-[#F4EADF]">
      <div className="mx-auto grid h-full max-w-[1600px] grid-rows-[minmax(0,1fr)] lg:grid-cols-[minmax(0,1fr)_minmax(420px,500px)_380px]">
        <AmbientAside table={table} now={now} waiterCall={waiterCall} onCallWaiter={() => setWaiterOpen(true)}
          onCancelCall={() => setWaiterCall(null)} onReset={reset} />

        <main className="relative h-full min-h-0 min-w-0 border-[#2E241E] lg:border-x">
          <MenuView table={table} inCart={inCart} onOpen={d => setEditing({ dish: d })} onQuickAdd={quickAdd}
            onCallWaiter={() => setWaiterOpen(true)} onReset={reset} />

          {/* Barra de pedido en móvil (queda por encima del sello inferior) */}
          {(count > 0 || orders.length > 0) && (
            <div className="pointer-events-none absolute inset-x-0 bottom-[60px] z-30 px-4 lg:hidden">
              <button onClick={() => { setTab(count > 0 ? 'pedido' : 'seguimiento'); setOrderOpen(true); }}
                className="pointer-events-auto flex h-14 w-full items-center gap-3 rounded-full bg-[#F0642C] pl-2 pr-5 font-semibold text-[#15100D] shadow-2xl shadow-black/60 transition-transform active:scale-[.99]">
                {count > 0 ? (
                  <>
                    <span className="tabular grid h-10 min-w-10 place-items-center rounded-full bg-[#15100D] px-2 text-[#F4EADF]">{count}</span>
                    <span className="flex-1 text-left">Ver pedido</span>
                    <span className="tabular">{eur(cartTotal(cart))}</span>
                  </>
                ) : (
                  <>
                    <span className="grid h-10 w-10 place-items-center rounded-full bg-[#15100D] text-[#F0642C]"><ConciergeBell size={18} /></span>
                    <span className="flex-1 text-left">Ver seguimiento</span>
                    <span className="text-sm font-medium">{cooking ? plural(cooking, 'en marcha', 'en marcha') : 'Todo servido'}</span>
                  </>
                )}
                <ChevronUp size={18} aria-hidden />
              </button>
            </div>
          )}
        </main>

        <section aria-label="Tu pedido" className="hidden h-full min-h-0 lg:block">
          <OrderPanel {...panelProps} />
        </section>
      </div>

      {orderOpen && (
        <div className="fade-enter fixed inset-0 z-40 flex flex-col bg-black/60 lg:hidden" onClick={() => setOrderOpen(false)}>
          <div className="sheet-enter mt-10 flex min-h-0 flex-1 flex-col overflow-hidden rounded-t-3xl ring-1 ring-[#3A2E26]" onClick={e => e.stopPropagation()}>
            <OrderPanel {...panelProps} onClose={() => setOrderOpen(false)} />
          </div>
        </div>
      )}

      {editing && <DishSheet key={editing.line?.key ?? editing.dish.id} dish={editing.dish} line={editing.line} onClose={closeEditing} onSave={saveLine} />}
      {waiterOpen && <WaiterSheet table={table} onClose={closeWaiter} onCall={callWaiter} />}

      {toast && (
        <div key={toast.id} role="status"
          className="toast-enter fixed left-1/2 top-3 lg:bottom-10 lg:top-auto z-[60] w-max max-w-[calc(100%-32px)] -translate-x-1/2 rounded-full bg-[#F4EADF] px-4 py-2.5 text-sm font-semibold text-[#15100D] shadow-xl shadow-black/50 ">
          {toast.text}
        </div>
      )}
    </div>
  );
}

import { BellRing, Clock, MapPin, RotateCcw, UserRound, X } from 'lucide-react';
import { RESTAURANT } from '../data/menu';
import { IMG } from '../data/images';
import { ago } from '../lib/format';
import type { WaiterCall } from '../lib/store';

type Props = {
  table: number;
  now: number;
  waiterCall: WaiterCall | null;
  onCallWaiter: () => void;
  onCancelCall: () => void;
  onReset: () => void;
};

/** Columna ambiental de escritorio: foto del salón, datos del local y aviso al camarero. */
export default function AmbientAside({ table, now, waiterCall, onCallWaiter, onCancelCall, onReset }: Props) {
  return (
    <aside className="relative hidden h-full overflow-hidden bg-[#211915] lg:block">
      <img src={IMG('resto-interior')} alt="Salón del asador Brasa con mesas preparadas para la cena"
        className="absolute inset-0 h-full w-full object-cover" />
      <div className="absolute inset-0 bg-gradient-to-t from-[#15100D] via-[#15100D]/70 to-[#15100D]/25" />
      <div className="absolute inset-0 bg-[radial-gradient(70%_50%_at_20%_100%,rgba(240,100,44,.28),transparent_70%)]" />

      <div className="relative flex h-full flex-col justify-between p-8 xl:p-10">
        <div className="flex items-center gap-2 text-sm font-medium text-[#F4EADF]/85">
          <MapPin size={15} className="text-[#E9B45A]" /> {RESTAURANT.address}
        </div>

        <div>
          <p className="font-display text-[44px] font-semibold leading-[1.02] text-[#F4EADF] xl:text-[52px]">
            Leña de encina,<br />fuego lento.
          </p>
          <p className="mt-4 max-w-sm text-[15px] leading-relaxed text-[#E6D8C9]/85">
            Carnes maduradas en casa, verduras de la huerta de Aranjuez y pan de masa madre. Pide a tu ritmo: cocina marca cada pase al momento.
          </p>

          <dl className="mt-7 grid max-w-sm grid-cols-2 gap-3 text-sm">
            <div className="rounded-2xl bg-[#15100D]/70 p-3.5 ring-1 ring-[#F4EADF]/10 backdrop-blur">
              <dt className="flex items-center gap-1.5 text-[#B5A596]"><UserRound size={14} /> Tu mesa</dt>
              <dd className="font-display mt-1 text-2xl font-semibold text-[#F4EADF]">Mesa {table}</dd>
            </div>
            <div className="rounded-2xl bg-[#15100D]/70 p-3.5 ring-1 ring-[#F4EADF]/10 backdrop-blur">
              <dt className="flex items-center gap-1.5 text-[#B5A596]"><Clock size={14} /> Cocina</dt>
              <dd className="font-display mt-1 text-2xl font-semibold text-[#F4EADF]">hasta 23:30</dd>
            </div>
          </dl>

          {waiterCall ? (
            <div className="fade-enter mt-4 flex max-w-sm items-center gap-3 rounded-2xl bg-[#E9B45A]/15 p-3.5 ring-1 ring-[#E9B45A]/40 backdrop-blur">
              <span className="pulse-dot grid h-9 w-9 shrink-0 place-items-center rounded-full bg-[#E9B45A] text-[#15100D]"><BellRing size={17} /></span>
              <div className="min-w-0 flex-1 text-sm">
                <p className="font-semibold text-[#F4EADF]">{RESTAURANT.waiter} va de camino</p>
                <p className="truncate text-[#E6D8C9]/80">{waiterCall.reason} · {ago(waiterCall.at, now)}</p>
              </div>
              <button onClick={onCancelCall} aria-label="Cancelar aviso al camarero"
                className="grid h-8 w-8 place-items-center rounded-full text-[#E6D8C9] hover:bg-[#15100D]/60"><X size={16} /></button>
            </div>
          ) : (
            <button onClick={onCallWaiter}
              className="mt-4 inline-flex h-12 items-center gap-2 rounded-full bg-[#F4EADF] px-5 font-semibold text-[#15100D] transition-colors hover:bg-white">
              <BellRing size={18} className="text-[#C2491B]" /> Llamar al camarero
            </button>
          )}
        </div>

        <button onClick={onReset} className="inline-flex w-fit items-center gap-1.5 rounded-full text-xs text-[#B5A596] hover:text-[#F4EADF]">
          <RotateCcw size={13} /> Restablecer datos de ejemplo
        </button>
      </div>
    </aside>
  );
}

import { Bean, Egg, Fish, Flame, Leaf, Milk, Nut, Sprout, Wheat, WheatOff, Wine, type LucideIcon } from 'lucide-react';
import clsx from 'clsx';
import { ALLERGENS, TAGS, type Allergen, type Tag } from '../data/menu';

const ALLERGEN_ICON: Record<Allergen, LucideIcon> = {
  gluten: Wheat, lacteos: Milk, huevo: Egg, 'frutos-secos': Nut, pescado: Fish, soja: Bean, sulfitos: Wine,
};

const TAG_STYLE: Record<Tag, { icon: LucideIcon; cls: string }> = {
  picante: { icon: Flame, cls: 'text-[#FF8A5B] bg-[#F0642C]/15 ring-[#F0642C]/30' },
  vegetariano: { icon: Leaf, cls: 'text-[#9CC57A] bg-[#9CC57A]/10 ring-[#9CC57A]/30' },
  vegano: { icon: Sprout, cls: 'text-[#9CC57A] bg-[#9CC57A]/10 ring-[#9CC57A]/30' },
  'sin-gluten': { icon: WheatOff, cls: 'text-[#E9B45A] bg-[#E9B45A]/10 ring-[#E9B45A]/30' },
};

/** Iconos compactos de alérgenos (con nombre accesible y tooltip). */
export function AllergenIcons({ list, size = 14 }: { list: Allergen[]; size?: number }) {
  if (!list.length) return null;
  return (
    <ul className="flex items-center gap-1.5" aria-label="Alérgenos">
      {list.map(a => {
        const Icon = ALLERGEN_ICON[a];
        return (
          <li key={a} title={ALLERGENS[a]} className="grid h-6 w-6 place-items-center rounded-full bg-[#2E241E] text-[#CBB9A6]">
            <Icon size={size} aria-hidden />
            <span className="sr-only">{ALLERGENS[a]}</span>
          </li>
        );
      })}
    </ul>
  );
}

/** Lista de alérgenos con nombre, para el detalle del plato. */
export function AllergenList({ list }: { list: Allergen[] }) {
  if (!list.length) return <p className="text-sm text-[#B5A596]">Sin alérgenos de declaración obligatoria.</p>;
  return (
    <ul className="flex flex-wrap gap-2">
      {list.map(a => {
        const Icon = ALLERGEN_ICON[a];
        return (
          <li key={a} className="inline-flex items-center gap-1.5 rounded-full bg-[#2E241E] px-3 py-1.5 text-sm text-[#E6D8C9]">
            <Icon size={15} aria-hidden /> {ALLERGENS[a]}
          </li>
        );
      })}
    </ul>
  );
}

export function TagChip({ tag, compact }: { tag: Tag; compact?: boolean }) {
  const { icon: Icon, cls } = TAG_STYLE[tag];
  return (
    <span
      title={TAGS[tag]}
      className={clsx('inline-flex items-center gap-1 rounded-full ring-1 ring-inset font-medium', cls,
        compact ? 'h-6 w-6 justify-center' : 'px-2 py-0.5 text-xs')}
    >
      <Icon size={compact ? 13 : 12} aria-hidden />
      {compact ? <span className="sr-only">{TAGS[tag]}</span> : TAGS[tag]}
    </span>
  );
}

export const TAG_ICON = (t: Tag) => TAG_STYLE[t].icon;

import { Beef, CakeSlice, Pizza, Plus, Salad, UtensilsCrossed, Wine, type LucideIcon } from 'lucide-react';
import clsx from 'clsx';
import type { CategoryId, Dish } from '../data/menu';
import { IMG } from '../data/images';
import { eur } from '../lib/format';
import { AllergenIcons, TagChip } from './Badges';

export const CATEGORY_ICON: Record<CategoryId, LucideIcon> = {
  picar: UtensilsCrossed, brasa: Beef, huerta: Salad, lena: Pizza, postres: CakeSlice, bebidas: Wine,
};

/** Miniatura del plato: foto si la hay; si no, un azulejo de brasa con el icono de su categoría. */
export function DishThumb({ dish, className }: { dish: Dish; className?: string }) {
  if (dish.photo) {
    return (
      <img src={IMG(dish.photo)} alt={dish.name} loading="lazy"
        className={clsx('object-cover bg-[#2E241E]', className)} />
    );
  }
  const Icon = CATEGORY_ICON[dish.category];
  return (
    <div className={clsx('tile-ember grid place-items-center text-[#E9B45A]/80', className)} aria-hidden>
      <Icon size={30} strokeWidth={1.4} />
    </div>
  );
}

type RowProps = { dish: Dish; inCart: number; onOpen: () => void; onQuickAdd: () => void };

export function DishRow({ dish, inCart, onOpen, onQuickAdd }: RowProps) {
  return (
    <li className="relative">
      <button
        onClick={onOpen}
        className="group flex w-full gap-4 rounded-2xl px-3 py-3.5 text-left transition-colors hover:bg-[#211915]"
      >
        <div className="min-w-0 flex-1">
          <div className="flex items-start gap-2">
            <h3 className="font-semibold leading-snug text-[#F4EADF]">{dish.name}</h3>
          </div>
          <p className="mt-1 line-clamp-2 text-sm leading-relaxed text-[#B5A596]">{dish.description}</p>
          <div className="mt-2.5 flex flex-wrap items-center gap-x-3 gap-y-2">
            <span className="tabular font-semibold text-[#E9B45A]">{eur(dish.price)}</span>
            {dish.serves && <span className="text-xs text-[#B5A596]">{dish.serves}</span>}
            {dish.tags.length > 0 && (
              <span className="flex gap-1">{dish.tags.map(t => <TagChip key={t} tag={t} compact />)}</span>
            )}
            <AllergenIcons list={dish.allergens} size={12} />
          </div>
          {inCart > 0 && (
            <p className="mt-2 text-xs font-semibold text-[#F0642C]">{inCart} en tu pedido</p>
          )}
        </div>
        <DishThumb dish={dish} className="h-24 w-24 shrink-0 rounded-xl sm:h-[104px] sm:w-[104px]" />
      </button>
      <button
        onClick={onQuickAdd}
        aria-label={`Añadir ${dish.name}`}
        className="absolute bottom-1.5 right-1.5 grid h-9 w-9 place-items-center rounded-full bg-[#F0642C] text-[#15100D] shadow-lg shadow-black/40 ring-4 ring-[#15100D] transition-transform hover:scale-105 active:scale-95"
      >
        <Plus size={18} strokeWidth={2.6} />
      </button>
    </li>
  );
}

/** Tarjeta grande con foto para la fila de recomendados. */
export function FeaturedCard({ dish, onOpen }: { dish: Dish; onOpen: () => void }) {
  return (
    <button
      onClick={onOpen}
      className="group relative h-52 w-64 shrink-0 overflow-hidden rounded-2xl bg-[#2E241E] text-left"
    >
      <DishThumb dish={dish} className="absolute inset-0 h-full w-full transition-transform duration-500 group-hover:scale-105" />
      <div className="absolute inset-0 bg-gradient-to-t from-[#15100D] via-[#15100D]/45 to-transparent" />
      {dish.serves && (
        <span className="absolute left-3 top-3 rounded-full bg-[#15100D]/80 px-2.5 py-1 text-xs font-semibold text-[#F4EADF] backdrop-blur">
          {dish.serves}
        </span>
      )}
      <div className="absolute inset-x-0 bottom-0 p-4">
        <p className="font-display text-lg font-semibold leading-tight text-[#F4EADF]">{dish.name}</p>
        <p className="tabular mt-1 font-semibold text-[#E9B45A]">{eur(dish.price)}</p>
      </div>
    </button>
  );
}

import { useEffect, useState } from 'react';
import { Check, Minus, Plus, X } from 'lucide-react';
import clsx from 'clsx';
import { DONENESS, type Dish } from '../data/menu';
import { eur } from '../lib/format';
import { newKey, unitPrice, type CartLine } from '../lib/store';
import { AllergenList, TagChip } from './Badges';
import { DishThumb } from './DishCard';

type Props = {
  dish: Dish;
  line?: CartLine;
  onClose: () => void;
  onSave: (line: CartLine) => void;
};

const NOTE_MAX = 120;

export default function DishSheet({ dish, line, onClose, onSave }: Props) {
  const [qty, setQty] = useState(line?.qty ?? 1);
  const [extras, setExtras] = useState<string[]>(line?.extras ?? []);
  const [doneness, setDoneness] = useState<string | undefined>(line?.doneness ?? (dish.doneness ? 'Al punto' : undefined));
  const [notes, setNotes] = useState(line?.notes ?? '');

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const total = unitPrice({ dishId: dish.id, extras }) * qty;
  const toggle = (id: string) => setExtras(xs => (xs.includes(id) ? xs.filter(x => x !== id) : [...xs, id]));
  const save = () => onSave({ key: line?.key ?? newKey(), dishId: dish.id, qty, extras, doneness, notes: notes.trim() });

  return (
    <div className="fade-enter fixed inset-0 z-50 flex items-end justify-center bg-black/65 sm:items-center sm:p-6" onClick={onClose}>
      <div role="dialog" aria-modal="true" aria-labelledby="dish-title" onClick={e => e.stopPropagation()}
        className="sheet-enter relative flex max-h-[92dvh] w-full max-w-[480px] flex-col overflow-hidden rounded-t-3xl bg-[#1B1411] ring-1 ring-[#3A2E26] sm:rounded-3xl">
        <button onClick={onClose} aria-label="Cerrar"
          className="absolute right-3 top-3 z-10 grid h-9 w-9 place-items-center rounded-full bg-[#15100D]/80 text-[#F4EADF] backdrop-blur hover:bg-[#15100D]">
          <X size={18} />
        </button>
        <div className="thin-scroll overflow-y-auto">
          <DishThumb dish={dish} className={clsx('w-full', dish.photo ? 'h-56' : 'h-36')} />
          <div className="px-5 pb-6 pt-5">
            <div className="flex items-start justify-between gap-4">
              <h2 id="dish-title" className="font-display text-2xl font-semibold leading-tight text-[#F4EADF]">{dish.name}</h2>
              <span className="tabular pt-1 text-lg font-semibold text-[#E9B45A]">{eur(dish.price)}</span>
            </div>
            {dish.serves && <p className="mt-1 text-sm font-medium text-[#E9B45A]">{dish.serves}</p>}
            <p className="mt-2 leading-relaxed text-[#CBB9A6]">{dish.description}</p>
            {dish.tags.length > 0 && <div className="mt-3 flex flex-wrap gap-1.5">{dish.tags.map(t => <TagChip key={t} tag={t} />)}</div>}

            <h3 className="mt-6 text-sm font-semibold text-[#F4EADF]">Alérgenos</h3>
            <div className="mt-2"><AllergenList list={dish.allergens} /></div>

            {dish.doneness && (
              <fieldset className="mt-6">
                <legend className="text-sm font-semibold text-[#F4EADF]">Punto de la carne <span className="font-normal text-[#B5A596]">· obligatorio</span></legend>
                <div className="mt-2 grid grid-cols-3 gap-2">
                  {DONENESS.map(d => (
                    <button key={d} type="button" onClick={() => setDoneness(d)} aria-pressed={doneness === d}
                      className={clsx('rounded-xl px-2 py-2.5 text-sm font-semibold ring-1 transition-colors',
                        doneness === d ? 'bg-[#F0642C] text-[#15100D] ring-[#F0642C]' : 'text-[#E6D8C9] ring-[#3A2E26] hover:ring-[#5A483B]')}>
                      {d}
                    </button>
                  ))}
                </div>
              </fieldset>
            )}

            {dish.extras && dish.extras.length > 0 && (
              <fieldset className="mt-6">
                <legend className="text-sm font-semibold text-[#F4EADF]">{dish.category === 'brasa' ? 'Acompaña con' : 'Extras'} <span className="font-normal text-[#B5A596]">· opcional</span></legend>
                <ul className="mt-2 divide-y divide-[#2E241E] rounded-xl ring-1 ring-[#2E241E]">
                  {dish.extras.map(x => {
                    const on = extras.includes(x.id);
                    return (
                      <li key={x.id}>
                        <button type="button" onClick={() => toggle(x.id)} aria-pressed={on}
                          className="flex w-full items-center gap-3 px-3.5 py-3 text-left hover:bg-[#211915]">
                          <span className={clsx('grid h-5 w-5 place-items-center rounded-md ring-1 transition-colors',
                            on ? 'bg-[#E9B45A] text-[#15100D] ring-[#E9B45A]' : 'ring-[#5A483B]')}>
                            {on && <Check size={14} strokeWidth={3} />}
                          </span>
                          <span className="flex-1 text-[15px] text-[#E6D8C9]">{x.name}</span>
                          <span className="tabular text-sm text-[#B5A596]">+{eur(x.price)}</span>
                        </button>
                      </li>
                    );
                  })}
                </ul>
              </fieldset>
            )}

            <label className="mt-6 block">
              <span className="flex justify-between text-sm font-semibold text-[#F4EADF]">
                Notas para cocina
                <span className={clsx('font-normal tabular', notes.length >= NOTE_MAX ? 'text-[#FF8A5B]' : 'text-[#8F8072]')}>{notes.length}/{NOTE_MAX}</span>
              </span>
              <textarea value={notes} maxLength={NOTE_MAX} rows={2} onChange={e => setNotes(e.target.value)}
                placeholder="Ej.: sin cebolla, salsa aparte, alergia a…"
                className="mt-2 w-full resize-none rounded-xl bg-[#211915] px-3.5 py-3 text-[15px] text-[#F4EADF] ring-1 ring-[#3A2E26] placeholder:text-[#8F8072] focus:outline-none focus:ring-[#E9B45A]" />
            </label>
          </div>
        </div>

        <div className="flex items-center gap-3 border-t border-[#2E241E] bg-[#1B1411] px-5 py-4">
          <div className="flex items-center rounded-full ring-1 ring-[#3A2E26]">
            <button onClick={() => setQty(q => Math.max(1, q - 1))} disabled={qty <= 1} aria-label="Quitar uno"
              className="grid h-11 w-11 place-items-center rounded-full text-[#F4EADF] disabled:opacity-35"><Minus size={17} /></button>
            <span className="tabular w-6 text-center font-semibold text-[#F4EADF]" aria-live="polite">{qty}</span>
            <button onClick={() => setQty(q => Math.min(20, q + 1))} aria-label="Añadir uno"
              className="grid h-11 w-11 place-items-center rounded-full text-[#F4EADF]"><Plus size={17} /></button>
          </div>
          <button onClick={save} disabled={dish.doneness && !doneness}
            className="flex h-12 flex-1 items-center justify-between rounded-full bg-[#F0642C] px-5 font-semibold text-[#15100D] transition-colors hover:bg-[#FF7740] active:scale-[.99]">
            <span>{line ? 'Guardar cambios' : 'Añadir al pedido'}</span>
            <span className="tabular">{eur(total)}</span>
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { BellRing, Flame, RotateCcw, Search, X } from 'lucide-react';
import clsx from 'clsx';
import { CATEGORIES, DISHES, RESTAURANT, type CategoryId, type Dish, type Tag } from '../data/menu';
import { DishRow, FeaturedCard } from './DishCard';

type Filter = Exclude<Tag, 'picante'> | 'sin-picante';
const FILTERS: { id: Filter; label: string }[] = [
  { id: 'vegetariano', label: 'Vegetariano' },
  { id: 'vegano', label: 'Vegano' },
  { id: 'sin-gluten', label: 'Sin gluten' },
  { id: 'sin-picante', label: 'Sin picante' },
];

const matches = (d: Dish, q: string, filters: Filter[]) => {
  const text = `${d.name} ${d.description}`.toLowerCase();
  if (q && !text.includes(q.toLowerCase())) return false;
  return filters.every(f => (f === 'sin-picante' ? !d.tags.includes('picante') : d.tags.includes(f)));
};

type Props = {
  table: number;
  inCart: (dishId: string) => number;
  onOpen: (dish: Dish) => void;
  onQuickAdd: (dish: Dish) => void;
  onCallWaiter: () => void;
  onReset: () => void;
};

export default function MenuView({ table, inCart, onOpen, onQuickAdd, onCallWaiter, onReset }: Props) {
  const scroller = useRef<HTMLDivElement>(null);
  const bar = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState<CategoryId>('picar');
  const [query, setQuery] = useState('');
  const [filters, setFilters] = useState<Filter[]>([]);
  const lockUntil = useRef(0);

  const visible = useMemo(() => DISHES.filter(d => matches(d, query.trim(), filters)), [query, filters]);
  const sections = CATEGORIES.map(c => ({ ...c, dishes: visible.filter(d => d.category === c.id) })).filter(s => s.dishes.length);
  const featured = DISHES.filter(d => d.photo);
  const filtering = query.trim() !== '' || filters.length > 0;

  // Categoría activa según el scroll
  useEffect(() => {
    const el = scroller.current;
    if (!el) return;
    const onScroll = () => {
      if (Date.now() < lockUntil.current) return;
      const limit = el.getBoundingClientRect().top + (bar.current?.offsetHeight ?? 0) + 24;
      let current = sections[0]?.id;
      for (const s of sections) {
        const node = document.getElementById(`cat-${s.id}`);
        if (node && node.getBoundingClientRect().top <= limit) current = s.id;
      }
      if (current) setActive(current);
    };
    onScroll();
    el.addEventListener('scroll', onScroll, { passive: true });
    return () => el.removeEventListener('scroll', onScroll);
  }, [sections.map(s => s.id).join()]);

  const goTo = (id: CategoryId) => {
    const el = scroller.current;
    const node = document.getElementById(`cat-${id}`);
    setActive(id);
    lockUntil.current = Date.now() + 900;
    if (!el || !node) return;
    const offset = node.getBoundingClientRect().top - el.getBoundingClientRect().top + el.scrollTop - (bar.current?.offsetHeight ?? 0) - 4;
    el.scrollTo({ top: offset, behavior: 'smooth' });
  };

  const toggle = (f: Filter) => setFilters(fs => (fs.includes(f) ? fs.filter(x => x !== f) : [...fs, f]));
  const hour = new Date().getHours();
  const greeting = hour < 14 && hour >= 6 ? 'Buenos días' : hour < 21 && hour >= 14 ? 'Buenas tardes' : 'Buenas noches';

  return (
    <div ref={scroller} className="thin-scroll h-full overflow-y-auto">
      <header className="ember-glow px-5 pb-5 pt-5">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="grid h-9 w-9 place-items-center rounded-full bg-[#F0642C] text-[#15100D]"><Flame size={19} strokeWidth={2.4} /></span>
            <span className="font-display text-2xl font-semibold text-[#F4EADF]">{RESTAURANT.name}</span>
          </div>
          <button onClick={onCallWaiter}
            className="inline-flex items-center gap-2 rounded-full bg-[#2E241E] px-3.5 py-2 text-sm font-semibold text-[#F4EADF] ring-1 ring-[#4A3A2F] hover:bg-[#3A2E26] lg:hidden">
            <BellRing size={16} className="text-[#E9B45A]" /> Llamar al camarero
          </button>
        </div>
        <h1 className="font-display mt-6 text-[28px] font-semibold leading-tight text-[#F4EADF]">{greeting}, mesa {table}</h1>
        <p className="mt-1.5 text-[15px] text-[#B5A596]">Pide desde aquí y te lo llevamos a la mesa. {RESTAURANT.kitchenHours}.</p>

        <label className="mt-5 flex items-center gap-2.5 rounded-xl bg-[#211915] px-3.5 ring-1 ring-[#3A2E26] focus-within:ring-[#E9B45A]">
          <Search size={17} className="text-[#B5A596]" aria-hidden />
          <span className="sr-only">Buscar en la carta</span>
          <input value={query} onChange={e => setQuery(e.target.value)} placeholder="Buscar plato o ingrediente"
            className="h-11 min-w-0 flex-1 bg-transparent text-[15px] text-[#F4EADF] placeholder:text-[#8F8072] focus:outline-none" />
          {query && (
            <button onClick={() => setQuery('')} aria-label="Borrar búsqueda" className="rounded-full p-1 text-[#B5A596] hover:text-[#F4EADF]"><X size={16} /></button>
          )}
        </label>
        <div className="no-scrollbar -mx-5 mt-3 flex gap-2 overflow-x-auto px-5">
          {FILTERS.map(f => (
            <button key={f.id} onClick={() => toggle(f.id)} aria-pressed={filters.includes(f.id)}
              className={clsx('shrink-0 rounded-full px-3 py-1.5 text-sm font-medium ring-1 transition-colors',
                filters.includes(f.id) ? 'bg-[#E9B45A] text-[#15100D] ring-[#E9B45A]' : 'text-[#D9C9B8] ring-[#3A2E26] hover:ring-[#5A483B]')}>
              {f.label}
            </button>
          ))}
        </div>
      </header>

      <div ref={bar} className="sticky top-0 z-20 flex items-center border-b border-[#2E241E] bg-[#15100D]/95 backdrop-blur">
        <nav aria-label="Categorías" className="no-scrollbar flex min-w-0 flex-1 gap-1 overflow-x-auto px-4 py-2.5">
          {CATEGORIES.map(c => {
            const has = sections.some(s => s.id === c.id);
            return (
              <button key={c.id} role="tab" aria-selected={active === c.id} disabled={!has} onClick={() => goTo(c.id)}
                className={clsx('shrink-0 rounded-full px-3.5 py-2 text-sm font-semibold transition-colors disabled:opacity-35',
                  active === c.id ? 'bg-[#F4EADF] text-[#15100D]' : 'text-[#CBB9A6] hover:bg-[#211915]')}>
                {c.name}
              </button>
            );
          })}
        </nav>
        <button onClick={onCallWaiter} aria-label="Llamar al camarero" title="Llamar al camarero"
          className="mr-3 grid h-9 w-9 shrink-0 place-items-center rounded-full bg-[#2E241E] text-[#E9B45A] ring-1 ring-[#4A3A2F] hover:bg-[#3A2E26] lg:hidden">
          <BellRing size={16} />
        </button>
      </div>

      {!filtering && (
        <section className="pt-6" aria-labelledby="recomendados">
          <h2 id="recomendados" className="font-display px-5 text-xl font-semibold text-[#F4EADF]">Recomendados de la casa</h2>
          <div className="no-scrollbar mt-3 flex gap-3 overflow-x-auto px-5 pb-1">
            {featured.map(d => <FeaturedCard key={d.id} dish={d} onOpen={() => onOpen(d)} />)}
          </div>
        </section>
      )}

      <div className="px-2 pb-36 lg:pb-16">
        {sections.map(s => (
          <section key={s.id} id={`cat-${s.id}`} className="pt-6" aria-labelledby={`h-${s.id}`}>
            <h2 id={`h-${s.id}`} className="font-display flex items-baseline justify-between px-3 text-xl font-semibold text-[#F4EADF]">
              {s.name}
              <span className="font-sans text-xs font-medium text-[#8F8072]">{s.dishes.length} platos</span>
            </h2>
            <ul className="mt-1 divide-y divide-[#2A201B]">
              {s.dishes.map(d => (
                <DishRow key={d.id} dish={d} inCart={inCart(d.id)} onOpen={() => onOpen(d)} onQuickAdd={() => onQuickAdd(d)} />
              ))}
            </ul>
          </section>
        ))}
        {sections.length === 0 && (
          <div className="mx-3 mt-8 rounded-2xl border border-dashed border-[#3A2E26] p-8 text-center">
            <p className="font-display text-lg text-[#F4EADF]">No hay platos con esos criterios</p>
            <p className="mt-1 text-sm text-[#B5A596]">Prueba con otra palabra o quita algún filtro.</p>
            <button onClick={() => { setQuery(''); setFilters([]); }}
              className="mt-4 rounded-full bg-[#2E241E] px-4 py-2 text-sm font-semibold text-[#F4EADF] hover:bg-[#3A2E26]">Ver toda la carta</button>
          </div>
        )}
        <p className="px-3 pt-8 text-xs leading-relaxed text-[#8F8072]">
          Precios con IVA incluido. Si tienes alguna alergia o intolerancia, indícalo en las notas del plato o pregunta a nuestro equipo.
        </p>
        <button onClick={onReset} className="mx-3 mt-4 inline-flex items-center gap-1.5 text-xs text-[#B5A596] hover:text-[#F4EADF] lg:hidden">
          <RotateCcw size={13} /> Restablecer datos de ejemplo
        </button>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Minus, Pencil, Plus, ShoppingBag, Trash2, X } from 'lucide-react';
import clsx from 'clsx';
import { dishById } from '../data/menu';
import { eur, plural } from '../lib/format';
import { cartCount, cartTotal, lineDetail, lineTotal, type CartLine, type Order, type WaiterCall } from '../lib/store';
import Tracking from './Tracking';

export type PanelTab = 'pedido' | 'seguimiento';

type Props = {
  tab: PanelTab;
  onTab: (t: PanelTab) => void;
  cart: CartLine[];
  orders: Order[];
  table: number;
  now: number;
  waiterCall: WaiterCall | null;
  onTable: (n: number) => void;
  onQty: (key: string, qty: number) => void;
  onRemove: (key: string) => void;
  onEdit: (line: CartLine) => void;
  onSend: () => void;
  onCallWaiter: (reason?: string) => void;
  onClose?: () => void;
};

export default function OrderPanel(p: Props) {
  const count = cartCount(p.cart);
  const active = p.orders.length;
  return (
    <div className="flex h-full flex-col bg-[#1B1411]">
      <div className="flex items-center gap-2 border-b border-[#2E241E] px-4 pb-3 pt-4">
        <div role="tablist" className="flex flex-1 gap-1 rounded-full bg-[#15100D] p-1 ring-1 ring-[#2E241E]">
          {(['pedido', 'seguimiento'] as PanelTab[]).map(t => (
            <button key={t} role="tab" aria-selected={p.tab === t} onClick={() => p.onTab(t)}
              className={clsx('flex flex-1 items-center justify-center gap-2 rounded-full px-3 py-2 text-sm font-semibold transition-colors',
                p.tab === t ? 'bg-[#2E241E] text-[#F4EADF]' : 'text-[#B5A596] hover:text-[#F4EADF]')}>
              {t === 'pedido' ? 'Tu pedido' : 'Seguimiento'}
              {t === 'pedido' && count > 0 && <span className="tabular grid h-5 min-w-5 place-items-center rounded-full bg-[#F0642C] px-1.5 text-xs text-[#15100D]">{count}</span>}
              {t === 'seguimiento' && active > 0 && <span className="tabular text-xs text-[#8F8072]">{active}</span>}
            </button>
          ))}
        </div>
        {p.onClose && (
          <button onClick={p.onClose} aria-label="Cerrar" className="grid h-10 w-10 place-items-center rounded-full text-[#F4EADF] hover:bg-[#2E241E]"><X size={20} /></button>
        )}
      </div>
      {p.tab === 'pedido' ? <Cart {...p} /> : (
        <Tracking orders={p.orders} now={p.now} waiterCall={p.waiterCall} onCallWaiter={p.onCallWaiter} onBackToMenu={p.onClose} />
      )}
    </div>
  );
}

function Cart({ cart, table, onTable, onQty, onRemove, onEdit, onSend, onClose }: Props) {
  const [tableText, setTableText] = useState(String(table));
  const [error, setError] = useState('');
  const total = cartTotal(cart);

  const commitTable = (v: string) => {
    setTableText(v);
    const n = Number(v);
    if (!v.trim()) return setError('Indica el número de tu mesa (lo verás en el soporte de la mesa).');
    if (!Number.isInteger(n) || n < 1 || n > 40) return setError('Las mesas van del 1 al 40.');
    setError('');
    onTable(n);
  };
  const send = () => {
    if (error || !tableText.trim()) return commitTable(tableText);
    onSend();
  };

  if (!cart.length) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center px-8 pb-16 text-center">
        <span className="grid h-14 w-14 place-items-center rounded-full bg-[#2E241E] text-[#E9B45A]"><ShoppingBag size={24} /></span>
        <p className="font-display mt-4 text-xl text-[#F4EADF]">Tu pedido está vacío</p>
        <p className="mt-1 text-sm text-[#B5A596]">Añade platos desde la carta con el botón +. Podrás revisarlos aquí antes de enviarlos a cocina.</p>
        {onClose && <button onClick={onClose} className="mt-5 rounded-full bg-[#2E241E] px-4 py-2 text-sm font-semibold text-[#F4EADF]">Ver la carta</button>}
      </div>
    );
  }

  return (
    <>
      <div className="thin-scroll flex-1 overflow-y-auto px-4 py-2">
        <ul className="divide-y divide-[#2E241E]">
          {cart.map(l => {
            const dish = dishById(l.dishId);
            if (!dish) return null;
            const detail = lineDetail(l);
            return (
              <li key={l.key} className="py-3.5">
                <div className="flex items-start gap-3">
                  <div className="min-w-0 flex-1">
                    <p className="font-semibold leading-snug text-[#F4EADF]">{dish.name}</p>
                    {detail && <p className="mt-0.5 text-sm text-[#B5A596]">{detail}</p>}
                    {l.notes && <p className="mt-0.5 text-sm italic text-[#CBB9A6]">“{l.notes}”</p>}
                  </div>
                  <span className="tabular font-semibold text-[#F4EADF]">{eur(lineTotal(l))}</span>
                </div>
                <div className="mt-2.5 flex items-center gap-1">
                  <div className="flex items-center rounded-full ring-1 ring-[#3A2E26]">
                    <button onClick={() => (l.qty > 1 ? onQty(l.key, l.qty - 1) : onRemove(l.key))} aria-label={`Quitar una ${dish.name}`}
                      className="grid h-8 w-8 place-items-center rounded-full text-[#F4EADF] hover:bg-[#2E241E]"><Minus size={14} /></button>
                    <span className="tabular w-5 text-center text-sm font-semibold text-[#F4EADF]">{l.qty}</span>
                    <button onClick={() => onQty(l.key, Math.min(20, l.qty + 1))} aria-label={`Añadir una ${dish.name}`}
                      className="grid h-8 w-8 place-items-center rounded-full text-[#F4EADF] hover:bg-[#2E241E]"><Plus size={14} /></button>
                  </div>
                  <button onClick={() => onEdit(l)} className="ml-auto inline-flex items-center gap-1.5 rounded-full px-2.5 py-1.5 text-sm text-[#CBB9A6] hover:bg-[#2E241E] hover:text-[#F4EADF]">
                    <Pencil size={14} /> Editar
                  </button>
                  <button onClick={() => onRemove(l.key)} aria-label={`Eliminar ${dish.name}`}
                    className="grid h-8 w-8 place-items-center rounded-full text-[#CBB9A6] hover:bg-[#2E241E] hover:text-[#FF8A5B]"><Trash2 size={15} /></button>
                </div>
              </li>
            );
          })}
        </ul>
      </div>

      <div className="border-t border-[#2E241E] px-4 pb-16 pt-4">
        <div className="flex items-center gap-3">
          <label htmlFor="mesa" className="text-sm font-semibold text-[#F4EADF]">Número de mesa</label>
          <input id="mesa" inputMode="numeric" value={tableText} onChange={e => commitTable(e.target.value.replace(/\D/g, '').slice(0, 2))}
            aria-invalid={!!error} aria-describedby={error ? 'mesa-error' : undefined}
            className={clsx('tabular ml-auto h-10 w-16 rounded-xl bg-[#211915] text-center font-semibold text-[#F4EADF] ring-1 focus:outline-none',
              error ? 'ring-[#FF8A5B]' : 'ring-[#3A2E26] focus:ring-[#E9B45A]')} />
        </div>
        {error && <p id="mesa-error" className="mt-2 text-sm text-[#FF8A5B]">{error}</p>}
        <div className="mt-4 flex items-baseline justify-between">
          <span className="text-[#B5A596]">Total · {plural(cartCount(cart), 'artículo', 'artículos')}</span>
          <span className="tabular font-display text-2xl font-semibold text-[#F4EADF]">{eur(total)}</span>
        </div>
        <button onClick={send}
          className="mt-3 flex h-12 w-full items-center justify-center gap-2 rounded-full bg-[#F0642C] font-semibold text-[#15100D] transition-colors hover:bg-[#FF7740] active:scale-[.99]">
          Enviar pedido a cocina
        </button>
        <p className="mt-2.5 max-w-[60%] text-xs leading-snug text-[#8F8072]">Se paga al final, en la mesa. IVA incluido.</p>
      </div>
    </>
  );
}

import { BellRing, ChefHat, ClipboardCheck, ConciergeBell, ReceiptText } from 'lucide-react';
import clsx from 'clsx';
import { RESTAURANT, dishById } from '../data/menu';
import { ago, clock, eur } from '../lib/format';
import { lineDetail, stageOf, stageTimes, type Order, type Stage, type WaiterCall } from '../lib/store';

const STEPS: { id: Stage; label: string; icon: typeof ChefHat }[] = [
  { id: 'recibido', label: 'Recibido', icon: ClipboardCheck },
  { id: 'cocina', label: 'En cocina', icon: ChefHat },
  { id: 'servido', label: 'Servido', icon: ConciergeBell },
];
const ORDER: Stage[] = ['recibido', 'cocina', 'servido'];

const STATUS_TEXT: Record<Stage, string> = {
  recibido: 'Cocina ha recibido tu pedido',
  cocina: 'Se está preparando en la brasa',
  servido: 'Servido en tu mesa. ¡Que aproveche!',
};

type Props = {
  orders: Order[];
  now: number;
  waiterCall: WaiterCall | null;
  onCallWaiter: (reason?: string) => void;
  onBackToMenu?: () => void;
};

export default function Tracking({ orders, now, waiterCall, onCallWaiter, onBackToMenu }: Props) {
  const tableTotal = orders.reduce((s, o) => s + o.total, 0);
  const sorted = [...orders].sort((a, b) => b.sentAt - a.sentAt);

  return (
    <div className="flex flex-1 flex-col overflow-hidden">
      <div className="thin-scroll flex-1 overflow-y-auto px-4 py-4">
        {waiterCall && (
          <div className="fade-enter mb-4 flex items-start gap-3 rounded-2xl bg-[#E9B45A]/10 p-3.5 ring-1 ring-[#E9B45A]/30">
            <span className="pulse-dot mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-full bg-[#E9B45A] text-[#15100D]"><BellRing size={16} /></span>
            <div className="text-sm">
              <p className="font-semibold text-[#F4EADF]">{RESTAURANT.waiter} va de camino a tu mesa</p>
              <p className="text-[#CBB9A6]">{waiterCall.reason} · {ago(waiterCall.at, now)}</p>
            </div>
          </div>
        )}

        {sorted.length === 0 && (
          <div className="py-12 text-center">
            <p className="font-display text-xl text-[#F4EADF]">Aún no has enviado nada</p>
            <p className="mt-1 text-sm text-[#B5A596]">Cuando envíes tu pedido podrás seguirlo aquí, paso a paso.</p>
            {onBackToMenu && <button onClick={onBackToMenu} className="mt-5 rounded-full bg-[#2E241E] px-4 py-2 text-sm font-semibold text-[#F4EADF]">Ver la carta</button>}
          </div>
        )}

        <ol className="space-y-4">
          {sorted.map(o => {
            const stage = stageOf(o, now);
            const idx = ORDER.indexOf(stage);
            const times = stageTimes(o);
            return (
              <li key={o.id} className="rounded-2xl bg-[#211915] p-4 ring-1 ring-[#2E241E]">
                <div className="flex items-baseline justify-between">
                  <p className="font-display text-lg font-semibold text-[#F4EADF]">Pedido {o.number}</p>
                  <p className="text-sm text-[#8F8072]">Mesa {o.table} · {clock(o.sentAt)}</p>
                </div>
                <p className={clsx('mt-0.5 text-sm font-medium', stage === 'servido' ? 'text-[#9CC57A]' : 'text-[#E9B45A]')} aria-live="polite">
                  {STATUS_TEXT[stage]}
                </p>

                <div className="mt-4 grid grid-cols-3">
                  {STEPS.map((s, i) => {
                    const done = i <= idx;
                    const current = i === idx && stage !== 'servido';
                    return (
                      <div key={s.id} className="relative flex flex-col items-center text-center">
                        {i > 0 && (
                          <span className={clsx('absolute right-1/2 top-4 h-0.5 w-full -translate-y-1/2 transition-colors duration-700', i <= idx ? 'bg-[#F0642C]' : 'bg-[#3A2E26]')} aria-hidden />
                        )}
                        <span className={clsx('relative grid h-8 w-8 place-items-center rounded-full transition-colors duration-500',
                          done ? 'bg-[#F0642C] text-[#15100D]' : 'bg-[#2E241E] text-[#8F8072]', current && 'pulse-dot')}>
                          <s.icon size={15} />
                        </span>
                        <span className={clsx('mt-1.5 text-xs font-semibold', done ? 'text-[#F4EADF]' : 'text-[#8F8072]')}>{s.label}</span>
                        <span className="tabular text-[11px] text-[#8F8072]">{done ? clock(times[i]) : '—'}</span>
                      </div>
                    );
                  })}
                </div>

                <ul className="mt-4 space-y-1 border-t border-[#2E241E] pt-3 text-sm">
                  {o.lines.map(l => {
                    const extra = [lineDetail(l), l.notes].filter(Boolean).join(' · ');
                    return (
                      <li key={l.key} className="min-w-0 text-[#CBB9A6]">
                        <p className="truncate"><span className="tabular text-[#F4EADF]">{l.qty}×</span> {dishById(l.dishId)?.name}</p>
                        {extra && <p className="truncate pl-6 text-xs text-[#8F8072]">{extra}</p>}
                      </li>
                    );
                  })}
                </ul>
                <p className="tabular mt-2 text-right text-sm font-semibold text-[#F4EADF]">{eur(o.total)}</p>
              </li>
            );
          })}
        </ol>
      </div>

      {sorted.length > 0 && (
        <div className="border-t border-[#2E241E] px-4 pb-16 pt-4">
          <div className="flex items-baseline justify-between">
            <span className="text-[#B5A596]">Consumido en la mesa</span>
            <span className="tabular font-display text-2xl font-semibold text-[#F4EADF]">{eur(tableTotal)}</span>
          </div>
          <button onClick={() => onCallWaiter('Pedir la cuenta')}
            className="mt-3 flex h-12 w-full items-center justify-center gap-2 rounded-full bg-[#2E241E] font-semibold text-[#F4EADF] ring-1 ring-[#4A3A2F] hover:bg-[#3A2E26]">
            <ReceiptText size={18} className="text-[#E9B45A]" /> Pedir la cuenta
          </button>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { BellRing, CircleHelp, Droplets, ReceiptText, MessageSquare, X, type LucideIcon } from 'lucide-react';
import clsx from 'clsx';
import { RESTAURANT } from '../data/menu';

const REASONS: { id: string; label: string; hint: string; icon: LucideIcon }[] = [
  { id: 'ayuda', label: 'Tengo una duda con la carta', hint: 'Alérgenos, raciones, recomendaciones', icon: CircleHelp },
  { id: 'mesa', label: 'Agua, pan o cubiertos', hint: 'Lo traemos en un momento', icon: Droplets },
  { id: 'cuenta', label: 'Pedir la cuenta', hint: 'Tarjeta, efectivo o Bizum', icon: ReceiptText },
  { id: 'otro', label: 'Otro motivo', hint: 'Escríbelo y se lo decimos', icon: MessageSquare },
];

type Props = { table: number; onClose: () => void; onCall: (reason: string) => void };

export default function WaiterSheet({ table, onClose, onCall }: Props) {
  const [reason, setReason] = useState('ayuda');
  const [text, setText] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const submit = () => {
    const r = REASONS.find(x => x.id === reason)!;
    if (reason === 'otro' && text.trim().length < 3) return setError('Cuéntanos brevemente qué necesitas.');
    onCall(reason === 'otro' ? text.trim() : r.label);
  };

  return (
    <div className="fade-enter fixed inset-0 z-50 flex items-end justify-center bg-black/65 sm:items-center sm:p-6" onClick={onClose}>
      <div role="dialog" aria-modal="true" aria-labelledby="waiter-title" onClick={e => e.stopPropagation()}
        className="sheet-enter w-full max-w-[440px] rounded-t-3xl bg-[#1B1411] px-5 pb-20 pt-5 ring-1 ring-[#3A2E26] sm:rounded-3xl sm:pb-6">
        <div className="flex items-start justify-between gap-4">
          <div>
            <h2 id="waiter-title" className="font-display text-2xl font-semibold text-[#F4EADF]">Llamar al camarero</h2>
            <p className="mt-1 text-sm text-[#B5A596]">Mesa {table} · Hoy te atiende {RESTAURANT.waiter}</p>
          </div>
          <button onClick={onClose} aria-label="Cerrar" className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-[#2E241E] text-[#F4EADF] hover:bg-[#3A2E26]">
            <X size={18} />
          </button>
        </div>

        <fieldset className="mt-5">
          <legend className="sr-only">Motivo del aviso</legend>
          <div className="space-y-2">
            {REASONS.map(r => {
              const on = reason === r.id;
              return (
                <button key={r.id} type="button" onClick={() => { setReason(r.id); setError(''); }} aria-pressed={on}
                  className={clsx('flex w-full items-center gap-3 rounded-2xl px-3.5 py-3 text-left ring-1 transition-colors',
                    on ? 'bg-[#E9B45A]/10 ring-[#E9B45A]' : 'ring-[#2E241E] hover:ring-[#4A3A2F]')}>
                  <span className={clsx('grid h-9 w-9 shrink-0 place-items-center rounded-full', on ? 'bg-[#E9B45A] text-[#15100D]' : 'bg-[#2E241E] text-[#E9B45A]')}>
                    <r.icon size={17} />
                  </span>
                  <span className="min-w-0">
                    <span className="block font-semibold text-[#F4EADF]">{r.label}</span>
                    <span className="block text-sm text-[#B5A596]">{r.hint}</span>
                  </span>
                </button>
              );
            })}
          </div>
        </fieldset>

        {reason === 'otro' && (
          <label className="mt-3 block">
            <span className="sr-only">Qué necesitas</span>
            <input autoFocus value={text} maxLength={80} onChange={e => { setText(e.target.value); setError(''); }}
              placeholder="Ej.: una trona para el bebé"
              aria-invalid={!!error}
              className={clsx('h-11 w-full rounded-xl bg-[#211915] px-3.5 text-[15px] text-[#F4EADF] ring-1 placeholder:text-[#8F8072] focus:outline-none',
                error ? 'ring-[#FF8A5B]' : 'ring-[#3A2E26] focus:ring-[#E9B45A]')} />
            {error && <span className="mt-1.5 block text-sm text-[#FF8A5B]">{error}</span>}
          </label>
        )}

        <button onClick={submit}
          className="mt-5 flex h-12 w-full items-center justify-center gap-2 rounded-full bg-[#E9B45A] font-semibold text-[#15100D] transition-colors hover:bg-[#F2C46F] active:scale-[.99]">
          <BellRing size={18} /> Avisar a {RESTAURANT.waiter}
        </button>
      </div>
    </div>
  );
}

