const eurFmt = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR', minimumFractionDigits: 2 });

/** 12.5 → "12,50 €" */
export const eur = (n: number) => eurFmt.format(n);

/** Hora corta "21:14" */
export const clock = (ms: number) =>
  new Date(ms).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });

/** "hace un momento", "hace 5 min", "hace 1 h" */
export function ago(ms: number, now = Date.now()) {
  const min = Math.floor((now - ms) / 60000);
  if (min < 1) return 'hace un momento';
  if (min < 60) return `hace ${min} min`;
  return `hace ${Math.floor(min / 60)} h`;
}

export const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`;

import { useEffect, useState } from 'react';
import { dishById } from '../data/menu';

export type CartLine = {
  key: string;
  dishId: string;
  qty: number;
  extras: string[];
  doneness?: string;
  notes: string;
};
/** `times`: instantes reales de En cocina y Servido (si cocina los marcó); si no, se simulan. */
export type Order = { id: string; number: number; table: number; lines: CartLine[]; total: number; sentAt: number; times?: [number, number] };
export type Stage = 'recibido' | 'cocina' | 'servido';
export type WaiterCall = { reason: string; at: number };

const PREFIX = 'brasa-carta:';

/** Estado guardado en localStorage, con valor inicial la primera vez. */
export function usePersistent<T>(key: string, initial: T | (() => T)) {
  const [value, setValue] = useState<T>(() => {
    try {
      const raw = localStorage.getItem(PREFIX + key);
      if (raw) return JSON.parse(raw) as T;
    } catch { /* sin almacenamiento */ }
    return typeof initial === 'function' ? (initial as () => T)() : initial;
  });
  useEffect(() => {
    try { localStorage.setItem(PREFIX + key, JSON.stringify(value)); } catch { /* sin almacenamiento */ }
  }, [key, value]);
  return [value, setValue] as const;
}

export function clearStorage() {
  try {
    Object.keys(localStorage).filter(k => k.startsWith(PREFIX)).forEach(k => localStorage.removeItem(k));
  } catch { /* nada */ }
}

export const newKey = () => Math.random().toString(36).slice(2, 9);

/** Precio unitario de una línea: plato + extras elegidos. */
export function unitPrice(line: Pick<CartLine, 'dishId' | 'extras'>) {
  const dish = dishById(line.dishId);
  if (!dish) return 0;
  const extras = (dish.extras ?? []).filter(e => line.extras.includes(e.id)).reduce((s, e) => s + e.price, 0);
  return dish.price + extras;
}
export const lineTotal = (l: CartLine) => unitPrice(l) * l.qty;
export const cartTotal = (lines: CartLine[]) => lines.reduce((s, l) => s + lineTotal(l), 0);
export const cartCount = (lines: CartLine[]) => lines.reduce((s, l) => s + l.qty, 0);

/** Texto con extras, punto y notas de una línea. */
export function lineDetail(l: CartLine) {
  const dish = dishById(l.dishId);
  const extras = (dish?.extras ?? []).filter(e => l.extras.includes(e.id)).map(e => e.name);
  return [l.doneness, ...extras].filter(Boolean).join(' · ');
}

/*
 * Simulación de cocina: en un local real el estado llega del TPV / pantalla de cocina.
 * Aquí avanza solo para que se pueda probar el seguimiento.
 */
export const TO_KITCHEN_MS = 8_000;
export const TO_SERVED_MS = 60_000;
export function stageTimes(order: Order): [number, number, number] {
  const [k, s] = order.times ?? [order.sentAt + TO_KITCHEN_MS, order.sentAt + TO_SERVED_MS];
  return [order.sentAt, k, s];
}
export function stageOf(order: Order, now: number): Stage {
  const [, k, s] = stageTimes(order);
  if (now >= s) return 'servido';
  if (now >= k) return 'cocina';
  return 'recibido';
}

